package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbSnapshotSortIteratorTest {

	@TempDir
	Path directory;

	@Test
	void bufferedSortRenewsInRequestedOrderWithoutReturningRemovedIds() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			try (Txn txn = store.getTxnManager().createReadTxn();
					RecordIterator sorted = sorted(store, txn)) {
				assertThat(sorted.next()).containsExactly(30, 5, 100, 10);
				long version = txn.version();
				store.startTransaction();
				store.removeTriplesByContext(10, 5, 100, 20, true, ignored -> {
				});
				store.storeTriple(40, 5, 100, 15, true);
				store.storeTriple(5, 5, 100, 5, true);
				store.commit();
				assertThat(txn.version()).isNotEqualTo(version);
				assertThat(sorted.next()).containsExactly(40, 5, 100, 15);
				assertThat(sorted.next()).containsExactly(20, 5, 100, 30);
				assertThat(sorted.next()).isNull();
			}
		}
	}

	@Test
	void renewalDuringMaterializationDiscardsMixedSnapshotRowsBeforeReturningAny() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			AtomicBoolean mutate = new AtomicBoolean(true);
			AtomicInteger opens = new AtomicInteger();
			try (Txn txn = store.getTxnManager().createReadTxn();
					RecordIterator sorted = new LmdbSnapshotSortIterator(txn, "cspo", () -> {
						opens.incrementAndGet();
						RecordIterator input = store.getTriples(txn, StatementOrder.S, -1, -1, -1, -1, true);
						return new RecordIterator() {
							@Override
							public long[] next() {
								long[] row = input.next();
								if (row != null && mutate.compareAndSet(true, false)) {
									long[] oldRow = row.clone();
									try {
										store.startTransaction();
										store.removeTriplesByContext(10, 5, 100, 20, true, ignored -> {
										});
										store.storeTriple(5, 5, 100, 5, true);
										store.commit();
									} catch (IOException failure) {
										throw new SailException(failure);
									}
									return oldRow;
								}
								return row;
							}

							@Override
							public void close() {
								input.close();
							}
						};
					})) {
				assertThat(sorted.next()).containsExactly(5, 5, 100, 5);
				assertThat(opens.get()).as("the materialization straddling a renewal must be discarded").isEqualTo(2);
				assertThat(sorted.next()).containsExactly(30, 5, 100, 10);
				assertThat(sorted.next()).containsExactly(20, 5, 100, 30);
				assertThat(sorted.next()).isNull();
			}
		}
	}

	@Test
	void pendingSeekSurvivesRenewalBeforeAndAfterSortPreparation() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			try (Txn txn = store.getTxnManager().createReadTxn();
					RecordIterator sorted = sorted(store, txn)) {
				assertThat(sorted.seekForward(0, 0, 0, 20)).isTrue();
				store.startTransaction();
				store.removeTriplesByContext(10, 5, 100, 20, true, ignored -> {
				});
				store.storeTriple(40, 5, 100, 25, true);
				store.commit();
				assertThat(sorted.next()).containsExactly(40, 5, 100, 25);
				assertThat(sorted.seekForward(0, 0, 0, 40)).isTrue();
				store.startTransaction();
				store.storeTriple(50, 5, 100, 35, true);
				store.storeTriple(60, 5, 100, 45, true);
				store.commit();
				assertThat(sorted.next()).containsExactly(60, 5, 100, 45);
				assertThat(sorted.next()).isNull();
			}
		}
	}

	@Test
	void bufferedRowsCannotEscapeAnInvalidatedPinnedSnapshot() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			try (Txn txn = store.getTxnManager().createReadTxnPinned(store::getDataRevision);
					RecordIterator sorted = sorted(store, txn)) {
				assertThat(sorted.next()).containsExactly(30, 5, 100, 10);
				store.getTxnManager().deactivate();
				store.getTxnManager().activate();
				assertThatThrownBy(sorted::next).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");
			}
		}
	}

	@Test
	void bufferedRowsCannotEscapeARetiredReaderLease() throws Exception {
		try (TripleStore store = store()) {
			seed(store);
			try (Txn txn = store.getTxnManager().createReadTxn();
					RecordIterator sorted = sorted(store, txn)) {
				assertThat(sorted.next()).containsExactly(30, 5, 100, 10);
				txn.close();
				try (Txn nextOwner = store.getTxnManager().createReadTxn()) {
					assertThatThrownBy(sorted::next).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");
					assertThat(store.countTriples(nextOwner, -1, -1, -1, -1, true)).isEqualTo(3);
				}
			}
		}
	}

	private TripleStore store() throws IOException {
		return new TripleStore(directory.toFile(), new LmdbStoreConfig(), null);
	}

	private static RecordIterator sorted(TripleStore store, Txn txn) throws IOException {
		return new LmdbSnapshotSortIterator(txn, "cspo",
				() -> store.getTriples(txn, StatementOrder.S, -1, -1, -1, -1, true));
	}

	private static void seed(TripleStore store) throws IOException {
		store.startTransaction();
		store.storeTriple(30, 5, 100, 10, true);
		store.storeTriple(10, 5, 100, 20, true);
		store.storeTriple(20, 5, 100, 30, true);
		store.commit();
	}
}
